<?php
namespace App\Http\Controllers;use App\Models\{FinancialTransaction,User};use App\Services\AuditLogger;use App\Services\Team\TeamAuthorization;use App\Services\Transactions\TransactionProjector;use App\Services\Wallet\WalletService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Validation\Rule;use Inertia\Inertia;
class TransactionsController extends Controller{private function owner():User{$a=Auth::user();$o=app(TeamAuthorization::class)->ownerFor($a)??$a;abort_unless(app(TeamAuthorization::class)->allows($a,$o,'manage_transactions'),403);return$o;}private function filters(Request$r):array{return$r->validate(['tab'=>['nullable',Rule::in(['main','wallet'])],'status'=>['nullable',Rule::in(['pending','processing','paid','completed','failed','cancelled','expired','refunded','partially_refunded','reversed','disputed'])],'type'=>['nullable','string','max:60'],'currency'=>['nullable','string','size:3','regex:/^[A-Z]{3}$/'],'search'=>['nullable','string','max:100'],'from'=>['nullable','date_format:Y-m-d'],'to'=>['nullable','date_format:Y-m-d','after_or_equal:from']]);}private function query(User$o,array$f){$q=FinancialTransaction::where('studio_owner_id',$o->id)->where('category',$f['tab']??'main');if($v=$f['status']??null)$q->where('status',$v);if($v=$f['type']??null)$q->where('transaction_type',$v);if($v=$f['currency']??null)$q->where('currency',$v);if($v=$f['from']??null)$q->where('occurred_at','>=',$v.' 00:00:00');if($v=$f['to']??null)$q->where('occurred_at','<=',$v.' 23:59:59');if($v=$f['search']??null)$q->where(fn($x)=>$x->where('description','like','%'.addcslashes($v,'%_').'%')->orWhere('provider_reference','like','%'.addcslashes($v,'%_').'%')->orWhere('uuid','like','%'.addcslashes($v,'%_').'%'));return$q->orderByDesc('occurred_at')->orderByDesc('id');}public function index(Request$r,TransactionProjector$p,WalletService$wallet){$o=$this->owner();$p->sync($o);$f=$this->filters($r);$tab=$f['tab']??'main';$rows=$this->query($o,$f)->paginate(20)->withQueryString()->through(fn($x)=>$this->row($x,$wallet));return Inertia::render('Settings/Transactions',['section'=>'transactions','tab'=>$tab,'filters'=>$f,'transactions'=>$rows,'types'=>\App\Support\TransactionTypes::LABELS]);}public function show(FinancialTransaction$t,WalletService$w){$o=$this->owner();abort_unless($t->studio_owner_id===$o->id,404);return response()->json($this->row($t,$w));}public function export(Request$r,TransactionProjector$p,WalletService$wallet,AuditLogger$a){$o=$this->owner();$p->sync($o);$f=$this->filters($r);$a->log('transactions.exported','financial-transactions',null,[],[],['studio_owner_id'=>$o->id,'tab'=>$f['tab']??'main']);$name='lenspic-transactions-'.now()->format('Y-m-d').'.csv';return response()->streamDownload(function()use($o,$f,$wallet){$out=fopen('php://output','w');fputcsv($out,['Date','Time','Transaction ID','Description','Category','Type','Status','Currency','Subtotal','Discount','Tax','Total','Credits Added','Credits Used','Payment Method','Provider Reference','Refund Status','Refund Amount']);$this->query($o,$f)->chunk(500,function($rows)use($out,$wallet){foreach($rows as$x){$r=$this->row($x,$wallet);$safe=fn($v)=>preg_match('/^[=+\-@]/',(string)$v)?"'".$v:$v;fputcsv($out,array_map($safe,[$x->occurred_at->format('Y-m-d'),$x->occurred_at->format('H:i:s'),$x->uuid,$x->description,$x->category,$x->transaction_type,$x->status,$x->currency,$this->minor($x->subtotal_amount_minor),$this->minor($x->discount_amount_minor),$this->minor($x->tax_amount_minor),$this->minor($x->total_amount_minor),$x->direction==='credit'?$r['credits']:null,$x->direction==='debit'?$r['credits']:null,$x->payment_method_summary,$x->provider_reference,$x->refund_state,$this->minor($x->refund_amount_minor)]));}});fclose($out);},$name,['Content-Type'=>'text/csv; charset=UTF-8']);}private function minor(?int$v):?string{return$v===null?null:number_format($v/100,2,'.','');}private function row(FinancialTransaction$x,WalletService$w):array{return['id'=>$x->uuid,'description'=>$x->description,'date'=>$x->occurred_at->toIso8601String(),'category'=>$x->category,'type'=>$x->transaction_type,'status'=>$x->status,'currency'=>$x->currency,'subtotal_minor'=>$x->subtotal_amount_minor,'discount_minor'=>$x->discount_amount_minor,'tax_minor'=>$x->tax_amount_minor,'total_minor'=>$x->total_amount_minor,'credits'=>$x->credit_units!==null?$w->format(abs($x->credit_units)):null,'direction'=>$x->direction,'provider'=>$x->payment_provider,'provider_reference'=>$x->provider_reference,'payment_method'=>$x->payment_method_summary?:'Online Payment','refund_state'=>$x->refund_state,'refund_amount_minor'=>$x->refund_amount_minor,'details'=>$x->safe_details?:[]];}}
